  "hooks": ["project:save"],
  "panels": [{ "id": "stats", "title": "故事統計", "html": "<!doctype html>…" }],
  "settings": [{ "key": "columns", "kind": "number", "label": "每列幾張卡片", "defaultValue": 4 }],
  "theme": { "--larch-ink": "#161a22" },
